//! Material Symbols as Rust constants: weight 400, 24 px grid, one path per icon in `viewBox="0 -960 960 960"`.
//!
//! The tables are generated by `tools/material-cdn` from `aphrody-labs/material-design-icons` (a fork of
//! `google/material-design-icons`, Apache-2.0), published to `https://material.aphrody.com/v1/rust/` and consumed here
//! at build time: vendored for `outlined` (offline), from the checksum-pinned CDN tarball for `rounded` and `sharp`.
//!
//! ```
//! use fw_material::{Style, svg};
//! let home = svg(Style::Outlined, "home", false).expect("home");
//! assert!(home.starts_with("<svg"));
//! ```

use std::fmt::Write as _;

pub mod cdn;

/// Version of the generated data, from the upstream commit (`YYYY.MMDD.patch`).
pub const VERSION: &str = env!("FW_MATERIAL_VERSION");
/// `vendored` or `cdn`: where the tables of this build came from.
pub const SOURCE: &str = env!("FW_MATERIAL_SOURCE_KIND");
/// View box shared by every path.
pub const VIEWBOX: &str = "0 -960 960 960";

/// `(name, Unicode codepoint)` sorted by name. The font ligature of an icon is its name.
pub static CODEPOINTS: &[(&str, u32)] = include!(concat!(env!("OUT_DIR"), "/codepoints.rs"));

#[cfg(feature = "outlined")]
static OUTLINED: &[(&str, &str)] = include!(concat!(env!("OUT_DIR"), "/outlined.rs"));
#[cfg(feature = "outlined")]
static OUTLINED_FILL: &[(&str, &str)] = include!(concat!(env!("OUT_DIR"), "/outlined_fill.rs"));
#[cfg(feature = "rounded")]
static ROUNDED: &[(&str, &str)] = include!(concat!(env!("OUT_DIR"), "/rounded.rs"));
#[cfg(feature = "rounded")]
static ROUNDED_FILL: &[(&str, &str)] = include!(concat!(env!("OUT_DIR"), "/rounded_fill.rs"));
#[cfg(feature = "sharp")]
static SHARP: &[(&str, &str)] = include!(concat!(env!("OUT_DIR"), "/sharp.rs"));
#[cfg(feature = "sharp")]
static SHARP_FILL: &[(&str, &str)] = include!(concat!(env!("OUT_DIR"), "/sharp_fill.rs"));

/// Material Symbols style; the matching Cargo feature must be enabled for its data to be present.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Style {
    Outlined,
    Rounded,
    Sharp,
}

impl Style {
    /// Directory name on the CDN: `icons/<slug>/<name>.svg`.
    pub const fn slug(self) -> &'static str {
        match self {
            Style::Outlined => "outlined",
            Style::Rounded => "rounded",
            Style::Sharp => "sharp",
        }
    }
}

/// `(name, path data)` sorted by name, or an empty slice when the style's feature is disabled.
pub fn table(style: Style, fill: bool) -> &'static [(&'static str, &'static str)] {
    match (style, fill) {
        #[cfg(feature = "outlined")]
        (Style::Outlined, false) => OUTLINED,
        #[cfg(feature = "outlined")]
        (Style::Outlined, true) => OUTLINED_FILL,
        #[cfg(feature = "rounded")]
        (Style::Rounded, false) => ROUNDED,
        #[cfg(feature = "rounded")]
        (Style::Rounded, true) => ROUNDED_FILL,
        #[cfg(feature = "sharp")]
        (Style::Sharp, false) => SHARP,
        #[cfg(feature = "sharp")]
        (Style::Sharp, true) => SHARP_FILL,
        #[allow(unreachable_patterns)]
        _ => &[],
    }
}

/// Unicode codepoint of an icon in the Material Symbols fonts.
pub fn codepoint(name: &str) -> Option<u32> {
    CODEPOINTS
        .binary_search_by_key(&name, |(n, _)| n)
        .ok()
        .map(|i| CODEPOINTS[i].1)
}

/// SVG path data (`d` attribute) of an icon.
pub fn path(style: Style, name: &str, fill: bool) -> Option<&'static str> {
    let t = table(style, fill);
    t.binary_search_by_key(&name, |(n, _)| n)
        .ok()
        .map(|i| t[i].1)
}

/// A complete, standalone SVG using `currentColor`, identical in shape to the CDN's `icons/<style>/<name>.svg`.
pub fn svg(style: Style, name: &str, fill: bool) -> Option<String> {
    path(style, name, fill).map(|d| format!(r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="{VIEWBOX}" fill="currentColor"><path d="{d}"/></svg>"#))
}

/// One `<symbol id="{id}">` for an inline sprite (`<use href="#{id}"/>`).
pub fn symbol(style: Style, name: &str, fill: bool, id: &str) -> Option<String> {
    path(style, name, fill)
        .map(|d| format!(r#"<symbol id="{id}" viewBox="{VIEWBOX}"><path d="{d}"/></symbol>"#))
}

/// An inline sprite of `(id, icon name)` pairs; unknown names are skipped and returned in the second element.
pub fn sprite<'a>(
    style: Style,
    fill: bool,
    icons: &[(&'a str, &'a str)],
) -> (String, Vec<&'a str>) {
    let mut out = String::from(r#"<svg xmlns="http://www.w3.org/2000/svg">"#);
    let mut missing = Vec::new();
    for (id, name) in icons {
        match symbol(style, name, fill, id) {
            Some(s) => out.push_str(&s),
            None => missing.push(*name),
        }
    }
    out.push_str("</svg>");
    (out, missing)
}

/// CDN URL of an icon, relative to a base such as `https://material.aphrody.com/v1`.
pub fn cdn_url(base: &str, style: Style, name: &str, fill: bool) -> String {
    let mut s = String::new();
    let _ = write!(
        s,
        "{}/icons/{}/{name}{}.svg",
        base.trim_end_matches('/'),
        style.slug(),
        if fill { "-fill" } else { "" }
    );
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    fn render_alpha(svg: &str, px: u32) -> Vec<u8> {
        let tree = resvg::usvg::Tree::from_str(
            &svg.replace("currentColor", "#000"),
            &resvg::usvg::Options::default(),
        )
        .expect("parse svg");
        let mut pixmap = resvg::tiny_skia::Pixmap::new(px, px).expect("pixmap");
        let scale = px as f32 / tree.size().width();
        resvg::render(
            &tree,
            resvg::tiny_skia::Transform::from_scale(scale, scale),
            &mut pixmap.as_mut(),
        );
        pixmap
            .data()
            .as_chunks::<4>()
            .0
            .iter()
            .map(|p| p[3])
            .collect()
    }

    #[test]
    fn tables_are_sorted_and_complete() {
        assert!(CODEPOINTS.len() > 4000, "codepoints: {}", CODEPOINTS.len());
        assert!(
            CODEPOINTS.windows(2).all(|w| w[0].0 < w[1].0),
            "codepoints must be sorted by name"
        );
        for fill in [false, true] {
            let t = table(Style::Outlined, fill);
            assert!(t.len() > 4000, "outlined fill={fill}: {}", t.len());
            assert!(t.windows(2).all(|w| w[0].0 < w[1].0));
            assert!(
                t.iter()
                    .all(|(_, d)| d.starts_with('M') || d.starts_with('m'))
            );
        }
    }

    #[test]
    fn lookups_match_the_font() {
        assert_eq!(codepoint("home"), Some(0xe9b2));
        assert_eq!(codepoint("no_such_icon"), None);
        assert!(path(Style::Outlined, "home", false).is_some_and(|d| d.len() > 20));
        assert_ne!(
            path(Style::Outlined, "home", false),
            path(Style::Outlined, "home", true)
        );
        assert_eq!(
            cdn_url(
                "https://material.aphrody.com/v1/",
                Style::Rounded,
                "home",
                true
            ),
            "https://material.aphrody.com/v1/icons/rounded/home-fill.svg"
        );
    }

    #[test]
    fn icons_render_through_resvg() {
        let px = 48;
        let outline = render_alpha(&svg(Style::Outlined, "home", false).unwrap(), px);
        let filled = render_alpha(&svg(Style::Outlined, "home", true).unwrap(), px);
        let covered = |a: &[u8]| a.iter().filter(|&&v| v > 127).count();
        let (o, f) = (covered(&outline), covered(&filled));
        assert!(o > 100, "outlined home covers {o} px");
        assert!(
            f > o,
            "filled home ({f} px) must cover more than outlined ({o} px)"
        );
        // The glyph is drawn inside the viewBox: the corner pixels stay transparent.
        assert_eq!(outline[0], 0);
        assert_eq!(outline[(px * px - 1) as usize], 0);
    }

    #[cfg(all(feature = "rounded", feature = "sharp"))]
    #[test]
    fn every_style_has_the_same_icons() {
        let names = |s| table(s, false).iter().map(|(n, _)| *n).collect::<Vec<_>>();
        assert_eq!(SOURCE, "cdn");
        assert_eq!(names(Style::Rounded), names(Style::Outlined));
        assert_eq!(names(Style::Sharp), names(Style::Outlined));
        assert_ne!(
            path(Style::Rounded, "home", false),
            path(Style::Sharp, "home", false)
        );
    }

    #[test]
    fn sprite_reports_unknown_names() {
        let (s, missing) = sprite(
            Style::Outlined,
            false,
            &[("i-home", "home"), ("i-x", "definitely_not_an_icon")],
        );
        assert!(s.contains(r#"<symbol id="i-home""#) && !s.contains("i-x"));
        assert_eq!(missing, ["definitely_not_an_icon"]);
    }
}
